/**
 * @method
 * @name dts_list_OnLoadCompleted
 * @description dts_list 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_list_OnLoadCompleted = async function(rowcount) {
    if (dts_list.errorMsg) {
        await $c.win.alert(dts_list.errorMsg);
    } else {

    }
};

/**
 * @method
 * @name dts_list_OnLoadError
 * @description dts_list 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_list_OnLoadError = async function() {
    await $c.win.alert(dts_list);
};

/**
 * @method
 * @name img_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_close_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    scwin.init();

    // 패널라운드 처리
    // PanelToGroupBox(panel_1);

    // fn_SetCode();
    // fn_GetParentValue();
    fn_Search();
};

/**
 * @method
 * @name btn_Tab1_SDate_onclick
 * @description btn_Tab1_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Tab1_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};

/**
 * @method
 * @name btn_Tab1_EDate_onclick
 * @description btn_Tab1_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Tab1_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    fn_Search(); // 조회 버튼

};

/**
 * @method
 * @name grd_list_OnDblClick
 * @description grd_list 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_list_OnDblClick = async function(row, colid) {
    if (colid === "INPUT_SEQ") {
        scwin.gOvrdue_occr_dd = dts_list.getCellData(row, "CBPI_OVRDUE_OCCR_DD");
        const options = {
            id: "ULDSTF39202",
            title: scwin.gOvrdue_occr_dd.substring(0, 4) + "-" + scwin.gOvrdue_occr_dd.substring(4, 6) + "-" + scwin.gOvrdue_occr_dd.substring(6, 8) + " 등록내역",
            type: "browserPopup",
            width: "680px",
            height: "400px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/dsclmgt/ULDSTF39202.gfm", options);
    }
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};
